from queueing import payload

def submit(owner, enqueue, *, batch_size=20):
    # Validate integer 1..100 before calling enqueue; reject bool and invalid values with ValueError.
    if not isinstance(batch_size, int):
        raise ValueError('batch_size must be an integer')
    if not (1 <= batch_size <= 100):
        raise ValueError('batch_size must be between 1 and 100')
    return enqueue(payload(owner, batch_size))

def payload(owner, *, batch_size=None):
    if batch_size is None:
        # legacy: no batch_size provided
        return {"owner": owner}
    else:
        return {"owner": owner, "batch_size": batch_size}

def execute(task, process):
    batch = task.get('batch_size', 20)
    # ensure it is int (should already be validated), but use as given
    return process(task["owner"], batch)

